{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 지하철역 근처 부설주차장 설치 제한 거리 기준",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제21조 제1항 제2호에 따르면, 부설주차장 설치가 제한될 수 있는 지역(주차장설치제한지역)은 「도시교통정비촉진법」 제42조에 따른 교통혼잡특별관리구역으로서 전철역, 지하철역과 환승센터 또는 복합환승센터의 가장 가까운 출입구로부터 직선거리 500m 이내의 지역입니다.",
          "b_ids": "주차장:제21조제1항제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
